INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Дефектология. Работа с обучающимися с задержкой психического развития', 'defektologiya-rabota-s-obuchayuschimisya-s-zaderzhkoy-psihicheskogo-razvitiya', 'Курс для дефектологов, которые работают с детьми задержкой психического развития и хотят улучшить свои компетенции в вопросе коррекции данного диагноза.', NULL, 'Специальное образование', 144, 'kpk', 'заочная с применением дистанционных образовательных технологий', 9360, '[{"number": 1, "title": "Специальная педагогика и психология"}, {"number": 2, "title": "Инклюзивное и интегративное образование"}, {"number": 3, "title": "Клинико-психолого-педагогическая характеристика детей с ЗПР"}, {"number": 4, "title": "Диагностика психического развития детей с ЗПР"}, {"number": 5, "title": "Обучение и воспитание детей с ЗПР"}, {"number": 6, "title": "Методики преподавания дисциплин"}, {"number": 7, "title": "Разработка и реализация"}, {"number": 8, "title": "Разработка и реализация СИПР"}, {"number": 9, "title": "Оценка учебно-познавательной деятельности детей с ЗПР"}]', '{"knowledge": ["Клинико-психолого-педагогической характеристики детей с ЗПР", "Диагностика психического развития детей с ЗПР", "Обучения и воспитания детей с ЗПР и оценка результатов", "Разработки и реализации АООП/АОП, СИПР"], "skills": ["проводить диагностику психического развития детей с ЗПР", "корректировать развитие детей с ЗПР", "разрабатывать программы АООП/АОП", "преподавать общеобразовательные дисциплины на основе специальных методик"], "abilities": ["коррекционной работы с обучающимися с задержкой психического развития"]}', NULL, 1, @start_order + 1);
INSERT IGNORE INTO courses (title, slug, description, target_audience_text, course_group, hours, program_type, learning_format, price, modules_json, outcomes_json, federal_registry_info, is_active, display_order) VALUES ('Дефектология. Работа с обучающимися с расстройствами аутистического спектра', 'defektologiya-rabota-s-obuchayuschimisya-s-rasstroystvami-autisticheskogo-spektra', 'Курс для дефектологов, которые работают с детьми с расстройствами аутистического спектра и хотят более эффективно организовывать коррекционную работу с ними.', NULL, 'Специальное образование', 144, 'kpk', 'заочная с применением дистанционных образовательных технологий', 9360, '[{"number": 1, "title": "Специальная педагогика и психология"}, {"number": 2, "title": "Инклюзивное и интегративное образование"}, {"number": 3, "title": "Клинико-психологическая характеристика детского аутизма и расстройств аутистического спектра"}, {"number": 4, "title": "Диагностические мероприятия для определения вида и характера РАС у ребенка"}, {"number": 5, "title": "Оказание коррекционной помощи при расстройствах аутистического спектра"}, {"number": 6, "title": "Разработка и реализация АООП/АОП"}, {"number": 7, "title": "Разработка и реализация СИПР"}, {"number": 8, "title": "Оценка учебно-познавательной деятельности детей с РАС"}]', '{"knowledge": ["Клинико-психолого-педагогической характеристики детей с РАС", "Диагностика психического развития детей с РАС", "Обучения и воспитания детей с ЗПР и оценка результатов", "Разработки и реализации АООП/АОП, СИПР"], "skills": ["проводить диагностику психического развития детей с РАС", "корректировать развитие детей с РАС", "разрабатывать программы АООП/АОП", "сопровождать детей с РАС, а также оказывать консультационную поддержку их семьям"], "abilities": ["коррекционной работы с обучающимися с расстройствами аутистического спектра"]}', NULL, 1, @start_order + 2);
